#include <stdio.h>

void totalDaCompra(void) {
    int camisa = 47;
    int bone = 28;
    int desconto = 15;

    int total = camisa + bone;
    printf("total: %d\n", total);
    printf("com desconto: %d\n", total - desconto);
}
